def semver_sort(versions):
    def make_key(v):
        # strip build metadata
        core = v.split('+', 1)[0]
        if '-' in core:
            main, prerelease = core.split('-', 1)
            has_prerelease = 0  # sorts before no prerelease
        else:
            main = core
            prerelease = None
            has_prerelease = 1

        major, minor, patch = (int(x) for x in main.split('.'))

        if prerelease is not None:
            ids = prerelease.split('.')
            pre_key = []
            for ident in ids:
                if ident.isdigit():
                    pre_key.append((0, int(ident)))
                else:
                    pre_key.append((1, ident))
        else:
            pre_key = []

        return (major, minor, patch, has_prerelease, pre_key)

    return sorted(versions, key=make_key)

